2	
3	/// A package name validated to be safe for use as a filesystem path
4	/// segment (no traversal, no absolute-path prefixes) and well-formed
5	/// enough to send upstream.
6	#[derive(Debug, Clone)]
7	pub struct PackageName {
8	    raw: String,
9	    /// The unscoped portion — for `@scope/name` this is `name`, for
10	    /// `name` this is the whole thing. Used to validate tarball
11	    /// filenames, which are always `<basename>-<version>.tgz`.
12	    basename: String,
13	}
14	
15	impl PackageName {
16	    pub fn parse(raw: &str) -> Result<Self, RegistryError> {
17	        let invalid = || RegistryError::InvalidPackageName { name: raw.to_string() };
18	        if raw.is_empty() || raw.len() > 214 {
19	            return Err(invalid());
20	        }
21	        let basename = if let Some(rest) = raw.strip_prefix('@') {
22	            let (scope, name) = rest.split_once('/').ok_or_else(invalid)?;
23	            if !is_safe_segment(scope) || !is_safe_segment(name) {
24	                return Err(invalid());
25	            }
26	            name.to_string()
27	        } else {
28	            if !is_safe_segment(raw) {
29	                return Err(invalid());
30	            }
31	            raw.to_string()
32	        };
33	        Ok(Self { raw: raw.to_string(), basename })
34	    }
35	
36	    pub fn as_str(&self) -> &str {
37	        &self.raw
38	    }
39	
40	    /// Validate that `filename` is a plausible tarball name for this
41	    /// package. Two forms are accepted:
42	    ///
43	    /// * `<basename>-<version>.tgz` — the canonical disk-and-URL form
44	    ///   verdaccio uses and what client GETs send (`/foo/-/foo-1.0.0.tgz`).
45	    /// * `<full-name>-<version>.tgz` — the form `libnpmpublish` puts in
46	    ///   the `_attachments` key of a publish body for scoped packages
47	    ///   (`@scope/name-1.0.0.tgz`). For unscoped packages this collapses
48	    ///   to the first form.
49	    pub fn validate_tarball_name(&self, filename: &str) -> Result<(), RegistryError> {
50	        self.canonicalize_tarball_name(filename).map(|_| ())
51	    }
52	
53	    /// Validate `filename` and return the canonical disk filename
54	    /// (`<basename>-<version>.tgz`). Used by the publish handler so
55	    /// libnpmpublish's `@scope/name-1.0.0.tgz` attachment lands on
56	    /// disk under the same path the GET endpoint serves.
57	    pub fn canonicalize_tarball_name(&self, filename: &str) -> Result<String, RegistryError> {
58	        self.parse_tarball_name(filename).map(|(canonical, _)| canonical)
59	    }
60	
61	    /// Like [`Self::canonicalize_tarball_name`] but also returns the
62	    /// version segment extracted from the filename. The publish
63	    /// handler uses the version to look up `versions[v].dist` and
64	    /// verify the tarball's integrity against what the packument
65	    /// declares.
66	    pub fn parse_tarball_name(&self, filename: &str) -> Result<(String, String), RegistryError> {
67	        let invalid = || RegistryError::InvalidTarballName {
68	            package: self.raw.clone(),
69	            filename: filename.to_string(),
70	        };
71	        let stem = filename.strip_suffix(".tgz").ok_or_else(invalid)?;
72	        // Try the longer prefix first so that for an unscoped package
73	        // (where `self.raw == self.basename`) we still match.
74	        let rest = stem
75	            .strip_prefix(&self.raw)
76	            .or_else(|| stem.strip_prefix(&self.basename))
77	            .ok_or_else(invalid)?;
78	        let version = rest.strip_prefix('-').ok_or_else(invalid)?;
79	        if !is_safe_segment(version) {
80	            return Err(invalid());
81	        }
82	        Ok((format!("{}-{}.tgz", self.basename, version), version.to_string()))
83	    }
84	}
85	
86	fn is_safe_segment(segment: &str) -> bool {
87	    !segment.is_empty()
88	        && !segment.starts_with('.')
89	        && !segment.contains('/')
90	        && !segment.contains('\\')
91	        && !segment.contains('\0')
92	        && segment != ".."
93	}
94	
