46	pub(crate) struct OsvIndex {
47	    packages: HashMap<String, Vec<Advisory>>,
48	    fingerprint: String,
49	}
50	
51	impl OsvIndex {
52	    pub(crate) fn load_from_config(config: &Config) -> Result<Option<Arc<Self>>, RegistryError> {
53	        if !config.osv.enabled {
54	            return Ok(None);
55	        }
56	        let path = config.osv.path.clone().unwrap_or_else(|| default_osv_path(config));
57	        if !path.exists() {
58	            return Err(invalid_config(format!(
59	                "OSV is enabled but database {} does not exist; download the npm OSV dump to this path or set osv.path",
60	                path.display(),
61	            )));
62	        }
63	        let index = Self::load_from_path(&path)?;
64	        // An enabled-but-empty index would make the guard a no-op and
65	        // silently disable enforcement, so treat it as misconfiguration.
66	        if index.packages.is_empty() {
67	            return Err(invalid_config(format!(
68	                "OSV is enabled but database {} yielded no npm advisories; check that the path points at the npm OSV dump",
69	                path.display(),
70	            )));
71	        }
72	        Ok(Some(Arc::new(index)))
73	    }
74	
75	    pub(crate) fn load_from_path(path: &Path) -> Result<Self, RegistryError> {
76	        if path.is_dir() {
77	            return load_from_directory(path);
78	        }
79	        // Only treat a regular file as a zip. Opening and streaming a
80	        // FIFO/socket/device for fingerprinting could block startup
81	        // indefinitely (the OSV DB loads before the listen socket binds),
82	        // so reject anything that isn't a directory or regular file.
83	        if path.is_file() {
84	            return load_from_zip(path);
85	        }
86	        Err(invalid_config(format!(
87	            "OSV database {} is neither a directory nor a regular file; point osv.path at the npm OSV dump (a .zip file or an extracted directory)",
88	            path.display(),
89	        )))
90	    }
91	
92	    pub(crate) fn policy(&self) -> serde_json::Map<String, serde_json::Value> {
93	        let mut policy = serde_json::Map::new();
94	        policy.insert(
95	            OSV_POLICY_KEY.to_string(),
96	            serde_json::Value::String(self.fingerprint.clone()),
97	        );
98	        policy
99	    }
100	
101	    pub(crate) fn can_trust_policy(
102	        &self,
103	        policy: &serde_json::Map<String, serde_json::Value>,
104	    ) -> bool {
105	        policy.get(OSV_POLICY_KEY).and_then(serde_json::Value::as_str)
106	            == Some(self.fingerprint.as_str())
107	    }
108	
109	    pub(crate) fn vulnerability_ids(&self, name: &str, version: &str) -> Vec<String> {
110	        let Some(advisories) = self.packages.get(normalized_name(name).as_ref()) else {
111	            return Vec::new();
112	        };
113	        // Parse the candidate once and share it across every advisory's
114	        // range check; exact-version advisories never need the parse.
115	        let parsed = Version::parse(version).ok();
116	        let mut seen = HashSet::new();
117	        advisories
118	            .iter()
119	            .filter(|advisory| advisory.affects(version, parsed.as_ref()))
120	            // A single OSV record can list the same package in several
121	            // `affected` blocks; dedup so one advisory id isn't repeated.
122	            .filter(|advisory| seen.insert(advisory.id.as_str()))
123	            .map(|advisory| advisory.id.clone())
124	            .collect()
125	    }
126	
127	    fn decision(&self, name: &str, version: &str) -> PackageVersionGuardDecision {
128	        let ids = self.vulnerability_ids(name, version);
129	        if ids.is_empty() {
130	            return PackageVersionGuardDecision::Allow;
131	        }
132	        PackageVersionGuardDecision::Reject {
133	            reason: format!(
134	                "is listed in the local OSV database as vulnerable ({})",
135	                format_advisory_ids(&ids),
136	            ),
137	        }
138	    }
139	}
