          "id": "GHSA-exact",
          "affected": [{
            "package": { "ecosystem": "npm", "name": "odd" },
            "versions": ["2026.06.18-custom"]
          }]
        }"#,
    )
    .expect("write record");

    let index = OsvIndex::load_from_path(dir.path()).expect("load index");

    assert_eq!(index.vulnerability_ids("odd", "2026.06.18-custom"), vec!["GHSA-exact"]);
}

