/// A packument version entry is eligible only when its key is a valid
/// semver string that matches the `version` field the entry declares.
/// A non-semver key can't be validated, and a key that disagrees with
/// the entry's own `version` is a spoofed/duplicated entry — both are
/// dropped so they can't be served or resolved.
fn version_entry_is_eligible(key: &str, entry: &Value) -> bool {
    node_semver::Version::parse(key).is_ok()
        && entry.get("version").and_then(Value::as_str) == Some(key)
}

/// A 403 for a tarball whose version an enabled OSV database flags as
/// vulnerable. The body names the package@version and the advisory
/// id(s) that flagged it, so a client (or a human reading the response)
/// can see why the download was refused.
fn vulnerable_tarball_response(package: &str, version: &str, ids: &[String]) -> Response {
    let body = format!(
        "Package {package}@{version} is listed in the local OSV database as vulnerable ({})",
        crate::resolver::format_advisory_ids(ids),
    );
    (StatusCode::FORBIDDEN, body).into_response()
